mapper.select:
/* selectMasterMdCtCustomerInfoManageList */ SELECT X.IRS_NO ,X.YYYY ,X.COM_NAME_LOC ,X.CEO_NAME_LOC ,X.CONGLOMERATE ,X.CREDIT_RATING ,X.YEAR_AMT ,X.EMP_CNT ,X.INDUSTRY_CODE ,(SELECT TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE = 'CP13' AND COD.CODE = X.INDUSTRY_CODE) AS INDUSTRY_TEXT ,X.TEL_NO ,X.ADDRESS_LOC ,TO_CHAR(X.ADD_DATETIME, 'YYYYMMDD') AS ADD_DATE ,X.ADD_USER_ID ,(SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = X.ADD_USER_ID) AS ADD_USER_NM ,TO_CHAR(X.CHANGE_DATETIME, 'YYYYMMDD') AS CHANGE_DATE ,X.CHANGE_USER_ID ,(SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = X.CHANGE_USER_ID) AS CHANGE_USER_NM FROM KEP.KEP_CUSTOMER_MST X WHERE 1=1
AND X.COM_NAME_LOC LIKE '%'||#{st_buyer} || '%'
AND REPLACE(X.IRS_NO,'-','') LIKE '%'|| REPLACE(#{st_irs_no},'-','') || '%'
AND TO_CHAR(X.ADD_DATETIME, 'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date}
AND TO_CHAR(X.CHANGE_DATETIME, 'YYYYMMDD') BETWEEN #{st_modify_from_date} AND #{st_modify_to_date}
AND X.ADD_USER_ID LIKE '%'||#{st_add_user_id} || '%'
AND X.CHANGE_USER_ID LIKE '%'||#{st_modify_user_id} || '%'
ORDER BY X.YYYY, X.COM_NAME_LOC

mapper.update:

/* updateMasterMdCtCustomerInfo */
UPDATE KEP.KEP_CUSTOMER_MST					
SET YYYY = #{YYYY}
	,COM_NAME_LOC = #{COM_NAME_LOC}
	,CEO_NAME_LOC = #{CEO_NAME_LOC}
	,CONGLOMERATE = #{CONGLOMERATE}
	,CREDIT_RATING = #{CREDIT_RATING}
	,YEAR_AMT = #{YEAR_AMT}
	,EMP_CNT = #{EMP_CNT}
	,INDUSTRY_CODE = #{INDUSTRY_CODE}
	,TEL_NO = #{TEL_NO}
	,ADDRESS_LOC = #{ADDRESS_LOC}
	,CHANGE_DATETIME = SYSDATE
	,CHANGE_USER_ID = #{st_user_id}
 WHERE REPLACE(IRS_NO,'-','') = REPLACE(#{IRS_NO},'-','')


/* insertMasterMdCtCustomerInfo */
INSERT INTO KEP.KEP_CUSTOMER_MST
(
 IRS_NO
 ,YYYY
 ,COM_NAME_LOC
 ,CEO_NAME_LOC
 ,CONGLOMERATE
 ,CREDIT_RATING
 ,YEAR_AMT
 ,EMP_CNT
 ,INDUSTRY_CODE
 ,TEL_NO
 ,ADDRESS_LOC
 ,ADD_DATETIME
 ,ADD_USER_ID
 ,CHANGE_DATETIME
 ,CHANGE_USER_ID
)VALUES
(
  SUBSTR(REPLACE(#{IRS_NO} ,'-',''),0,3)||'-'||SUBSTR(REPLACE(#{IRS_NO},'-',''),4,2)||'-'||SUBSTR(REPLACE(#{IRS_NO},'-',''),6,5)
  ,#{YYYY}
  ,#{COM_NAME_LOC}
  ,#{CEO_NAME_LOC}
  ,#{CONGLOMERATE}
  ,#{CREDIT_RATING}
  ,#{YEAR_AMT}
  ,#{EMP_CNT}
  ,#{INDUSTRY_CODE}
  ,#{TEL_NO}
  ,#{ADDRESS_LOC}
  ,SYSDATE
  ,#{st_user_id}
  ,SYSDATE
  ,#{st_user_id}
)
